'use strict';
(()=>{
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='SuperIsland.battery.requirement-draft.v3';
const defaults=()=>({enabled:true,limit:80,below80:false,autoDischarge:false,sailing:false,sailingLow:70,heat:false,heatLimit:35,sleep:'continue',stopOnExit:false,displayOff:'system',lockOnClose:false,lowPower:'battery',highPower:'never',backgroundUpdates:false,energyThreshold:'medium',includeBackground:false,catchUp:false,realPercentage:false,intelMode:false,led:'always',ledLimit:false,ledBlink:false,showStartup:false,showPercent:true,reduceTransparency:false,graphMode:'average',graphMinutes:15,widgets:['temperature','power','capacity','cycles','remaining','voltage'],indicators:['percentage','state'],indicatorStyle:'native',indicatorSpacing:5,indicatorInterval:5,indicatorRightClick:'settings',popupFields:['percentage','source','trend','controls']});
let p=defaults(),tasks=[],history=[];try{const v=JSON.parse(localStorage.getItem(storageKey)||'null');if(v){p={...p,...v.p};tasks=Array.isArray(v.tasks)?v.tasks:[];history=Array.isArray(v.history)?v.history:[]}}catch{}
const env={sleeping:false,lidClosed:false,appRunning:true,level:76,temp:30,plugged:true,scenario:'ok',now:new Date('2026-10-29T10:00:00+08:00').getTime()};
const r={pauseTarget:null,startupVisible:false,startupTitle:'',startupMessage:'',islandTab:'overview',trendHours:6,samples:[{time:env.now,level:env.level}],draftLimit:p.limit,mode:'auto',calStep:0,hold:0,calSaved:null,lastCalibration:null,error:'',retry:null,sailingHold:false,busy:false,lastOutput:'',lastChargeState:'idle',notice:'',busySerial:0};
let pane='battery',tab='charge',dialogCallback=null,pendingDialog=null,toastTimer;
const panes={general:'通用',modules:'模块',appearance:'外观',extensions:'扩展',windows:'窗口增强',screenshots:'截图挂绳',awake:'保持唤醒',battery:'电池管理',advanced:'高级'};
const tabs={dashboard:'仪表板',charge:'充电控制',sleep:'睡眠行为',energy:'能源使用',schedule:'定时设置',shortcuts:'捷径',display:'显示与面板',other:'其他'};
const steps=['充电至 100%','放电至 10%','再次充电至 100%','保持 100%','放电至原上限'];
const shortcutNames={topup:'充满',pause:'暂停充电',discharge:'开始放电',calibration:'启动校准',setLimit:'设置充电限制',getLevel:'获取电池百分比',getLimit:'获取充电限制',getState:'获取状态',getTemperature:'获取温度',setLED:'设置 MagSafe LED',setLow:'设置低功耗模式',setHigh:'设置高功率模式'};
const help={below80:'原软件提供独立开关，允许将充电限值设到 80% 以下。安装包的 SetPercentage 捷径参数范围为 20–100；界面与硬件的精确范围仍需复核。',autoDischarge:'开启后，若当前电量高于上限，自动放电至充电上限。',sailing:'达到上限后，允许电量下降到设定下限再开始充电；原软件文案明确低于 20% 时覆盖航海模式。下限字段的具体口径为本稿方案。',heat:'超过温度阈值时停止充电。恢复温度和回差未由现有证据确定，本稿用温度低于阈值恢复。',calibration:'安装包界面显示五阶段：100% → 10% → 100% → 保持 → 原限制。需接通电源；校准期间改变充电模式需先停止校准。保持时长本稿建议 120 分钟，未证实为原软件时长。',sleep:'原软件文案：睡眠时轮询频率降低，可能超过限制。睡眠时停止充电与达到上限前阻止休眠互斥。校准和合盖放电可能保持系统唤醒。',energy:'低功耗模式、背景仪表更新及高功耗应用筛选由原软件页面和资源确认；原生能源模式需要系统及硬件支持。',schedule:'原软件支持任务、模板、重复、错过补做及历史。任务编辑器被专业版锁定，具体字段和冲突策略是本稿候选方案。',hardware:'REA 从辅助程序元数据观察到 SMC 读写、休眠和电源模式方法；未反编译函数体，未验证 SuperIsland 有对应执行能力。'};
function autoEnableAtStartup(){const reason=block()||r.error;if(reason){p.enabled=false;r.startupTitle='电池管理未能自动启用';r.startupMessage=reason+'；请在电池设置中处理。本提示为模拟，不会自动安装辅助程序或授予权限。'}else{p.enabled=true;r.mode='auto';r.pauseTarget=null;r.startupTitle='电池管理已自动启用（模拟）';r.startupMessage='已按长期充电上限 '+p.limit+'% 启用管理。你可以在电池设置中查看或关闭；当前没有操作真实硬件。'}r.startupVisible=true;save();render()}
function save(){localStorage.setItem(storageKey,JSON.stringify({p,tasks,history}))}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200)}
function openDialog(title,body,actions){$('dialogTitle').textContent=title;$('dialogBody').innerHTML=body;$('dialogActions').innerHTML=actions.map((a,i)=>`<button data-dialog="${i}" class="${a.primary?'primary':''}">${esc(a.label)}</button>`).join('');dialogCallback=actions;$('dialogLayer').hidden=false;const focus=$('dialogActions').querySelector('button');focus?.focus()}
function closeDialog(){$('dialogLayer').hidden=true;dialogCallback=null}
function confirm(title,text,fn){openDialog(title,`<p>${esc(text)}</p>`,[{label:'取消'},{label:'确认（模拟）',primary:true,run:fn}])}
function block(){return env.scenario==='desktop'?'当前设备没有内置电池。':env.scenario==='conflict'?'检测到其他充电工具，需先处理冲突。':env.scenario==='denied'?'辅助程序未授权。':env.scenario==='fail'?'模拟控制失败，实际状态未知。':''}
function isIntel(){return p.intelMode||env.scenario==='intel'}
function chargeState(){if(!env.appRunning)return p.stopOnExit?'退出后保持停充':'应用退出，交还系统';if(env.sleeping&&p.sleep==='stop')return'睡眠时停止充电';if(r.error)return'待恢复';if(block())return'不可用';if(!p.enabled)return'管理关闭';if(!env.plugged)return'使用电池';if(p.heat&&env.temp>=p.heatLimit)return'过热保护';if(r.mode==='calibration')return'校准：'+steps[r.calStep];if(r.mode==='topup')return env.level>=100?'充满保持':'充满中';if(r.mode==='discharge')return env.level>p.limit?'放电中':'已到放电上限';if(r.mode==='pause')return'已临时暂停'+(r.pauseTarget!==null?' · '+r.pauseTarget+'%':'');if(p.sailing&&!isIntel()&&env.level>=20){if(env.level>=p.limit)r.sailingHold=true;if(env.level<=p.sailingLow)r.sailingHold=false;if(r.sailingHold)return'航海等待'}if(p.autoDischarge&&env.level>p.limit&&!isIntel())return'自动放电';return env.level<p.limit?'充电中':'达到充电上限'}
function preference(k,v){p[k]=v;if(k==='limit'){p.limit=Math.max(p.below80?20:80,Math.min(100,Math.round(Number(v)||80)));p.sailingLow=Math.min(p.sailingLow,p.limit-1)}if(k==='sailingLow')p.sailingLow=Math.max(20,Math.min(p.limit-1,Number(v)));if(k==='heatLimit')p.heatLimit=Math.max(25,Math.min(50,Number(v)));save();render()}
function log(title,result){history.unshift({title,result,time:env.now});history=history.slice(0,80);save()}
function operate(action,value){if(!env.appRunning){toast('请先模拟启动应用');return false}if(block()){r.error=block();r.retry={action,value};render();toast(r.error);return false}if(['discharge','topup','calibration'].includes(action)&&!env.plugged){toast('请先连接电源，再执行此操作。');return false}if(['discharge','calibration'].includes(action)&&isIntel()){toast('Intel 限制模式不支持此操作。');return false}if(action==='discharge'&&env.level<=p.limit){toast('放电目标必须低于当前电量；请降低充电上限。');return false}if(action==='setLimit'&&(!Number.isFinite(Number(value))||value<(p.below80?20:80)||value>100)){toast('当前允许范围为 '+(p.below80?'20':'80')+'–100%。');return false}
if(r.mode==='calibration'&&action!=='stopCalibration'&&!['sailing','heat'].includes(action)){confirm('停止校准并更改模式？','继续会中止当前校准并恢复原充电上限，然后执行新操作。',()=>{stopCalibration();operate(action,value)});return false}
r.error='';r.retry=null;if(action!=='pause')r.pauseTarget=null;if(action==='off'){p.enabled=false;r.mode='auto';r.sailingHold=false;r.startupVisible=false}else if(action==='on'){p.enabled=true;r.mode='auto'}else if(action==='setLimit'){p.limit=Number(value);r.draftLimit=p.limit;p.sailingLow=Math.min(p.sailingLow,p.limit-1);p.enabled=true;r.mode='auto'}else if(action==='pause'){if(r.mode==='pause'){r.mode='auto';r.pauseTarget=null}else{r.pauseTarget=env.level;p.enabled=true;r.mode='pause'}}else if(action==='topup'){p.enabled=true;r.mode=r.mode==='topup'?'auto':'topup'}else if(action==='discharge'){p.enabled=true;r.mode=r.mode==='discharge'?'auto':'discharge'}else if(action==='calibration'){confirm('开始完整校准？','模拟五阶段充放电。需要接电；开始后不能直接修改充电上限。使用验证面板推进流程。',()=>{p.enabled=true;r.calSaved=p.limit;r.calStep=0;r.hold=0;r.mode='calibration';save();render()});return false}else if(action==='stopCalibration'){confirm('停止校准？','中止五阶段流程并恢复校准前的充电限制。',()=>{stopCalibration();render();toast('已停止模拟校准并恢复原限制')});return false}else if(action==='auto'){r.mode='auto';p.enabled=true}save();render();return true}
function stopCalibration(){if(r.calSaved!==null)p.limit=r.calSaved;r.draftLimit=p.limit;r.calSaved=null;r.calStep=0;r.hold=0;r.mode='auto';save()}
function advanceBattery(){const state=chargeState();r.lastChargeState=state;if(!p.enabled||block()||!env.appRunning||(env.sleeping&&p.sleep==='stop'))return;if(!env.plugged){env.level=Math.max(0,env.level-5);r.mode='auto';return}if(state==='过热保护')return;if(r.mode==='calibration'){if(r.calStep===0||r.calStep===2){env.level=Math.min(100,env.level+10);if(env.level===100)r.calStep++}else if(r.calStep===1){env.level=Math.max(10,env.level-10);if(env.level===10)r.calStep++}else if(r.calStep===3){r.hold+=30;if(r.hold>=120)r.calStep++}else{env.level=Math.max(r.calSaved,env.level-10);if(env.level<=r.calSaved){r.lastCalibration=env.now;log('电池校准','五阶段模拟完成');stopCalibration()}}return}if(r.mode==='topup')env.level=Math.min(100,env.level+5);else if(r.mode==='discharge'||state==='自动放电'){env.level=Math.max(p.limit,env.level-5);if(env.level<=p.limit)r.mode='auto'}else if(state==='充电中')env.level=Math.min(p.limit,env.level+5);else if(state==='航海等待')env.level=Math.max(0,env.level-2)}
function calendarMonth(time){const d=new Date(time+8*3600e3),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);const end=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,end));return d.getTime()-8*3600e3}function nextWeekday(day,hour){const d=new Date(env.now+8*3600e3);d.setUTCHours(hour,0,0,0);const offset=(day-d.getUTCDay()+7)%7;d.setUTCDate(d.getUTCDate()+offset);if(d.getTime()-8*3600e3<=env.now)d.setUTCDate(d.getUTCDate()+7);return d.getTime()-8*3600e3}function executeTask(task,decision){if(r.mode==='calibration'&&!decision){openDialog('定时任务与校准冲突',`<p>任务“${esc(task.name)}”将改变当前校准状态。</p>`,[{label:'忽略本次',run:()=>{log(task.name,'因校准跳过');render()}},{label:'停止校准并执行',primary:true,run:()=>{stopCalibration();executeTask(task,'stop')}}]);return}let result=operate(task.action,task.value);log(task.name,result?'已在本地模拟执行':block()||'未执行或等待确认');render()}
function advance(){env.now+=30*60e3;advanceBattery();for(const task of tasks){if(!task.enabled||task.next>env.now)continue;const late=env.now-task.next>30*60e3;if(!late||p.catchUp)executeTask(task);else log(task.name,'错过时间且未开启补做');if(task.repeat==='daily')task.next+=86400e3;else if(task.repeat==='weekly')task.next+=7*86400e3;else if(task.repeat==='biweekly')task.next+=14*86400e3;else if(task.repeat==='monthly')task.next=calendarMonth(task.next);else task.enabled=false}save();render();toast('模拟时间已推进 30 分钟')}
function toggle(k){if(k==='intelMode'&&!p.intelMode&&['calibration','discharge'].includes(r.mode)){confirm('切换 Intel 模式？','将停止当前不兼容的模拟流程，并恢复充电限制。',()=>{if(r.mode==='calibration')stopCalibration();r.mode='auto';p.intelMode=true;save();render()});return}if(['sailing','autoDischarge'].includes(k)&&isIntel()){toast('Intel 限制模式不支持此选项');return}if(k==='below80'&&p[k]&&p.limit<80){confirm('关闭低于 80% 的充电限制？','当前上限将调整为 80%。',()=>{p.below80=false;p.limit=80;r.draftLimit=80;save();render()});return}p[k]=!p[k];save();render()}
function fieldToggle(k,title,note,helpKey,disabled=false){return row(title,`<input type="checkbox" data-pref="${k}" aria-label="${esc(title)}" ${p[k]?'checked':''} ${disabled?'disabled':''}>`,note,helpKey)}
function row(title,control,note='',helpKey=''){return `<div class="row"><div><strong>${title}</strong>${helpKey?`<button class="help" data-help="${helpKey}" aria-label="${esc(title.replace(/<[^>]*>/g,''))}帮助">?</button>`:''}${note?`<small>${note}</small>`:''}</div><div class="controls">${control}</div></div>`}
function options(list,current){return list.map(([value,label])=>`<option value="${value}" ${String(current)===String(value)?'selected':''}>${label}</option>`).join('')}
function select(k,list,label){return `<select data-pref="${k}" aria-label="${label||k}">${options(list,p[k])}</select>`}
function num(k,min,max,label){return `<input type="number" data-pref="${k}" min="${min}" max="${max}" value="${p[k]}" aria-label="${label}">`}
function stateBox(){return `<div class="status-card ${block()||r.error?'error':''}"><strong>${esc(chargeState())}</strong><p>模拟电量 ${env.level}% · ${env.temp}°C · 长期充电上限 ${p.limit}% · ${new Date(env.now).toLocaleString('zh-CN',{hour12:false})}</p>${r.error?`<p>${esc(r.error)}；不能视为已恢复。</p><button data-act="retry">重试控制</button>`:''}${env.scenario==='denied'?'<button data-act="authorize">模拟授权辅助程序</button>':''}</div>`}
function chargePage(){const intel=isIntel();return `<div class="box">${row('充电限制',`<input id="limitInput" type="number" data-limit-draft min="${p.below80?20:80}" max="100" value="${r.draftLimit}" aria-label="充电限制" ${r.mode==='calibration'?'disabled':''}> % <button data-act="applyLimit" class="primary" ${r.mode==='calibration'?'disabled':''}>应用</button>`,r.mode==='calibration'?'校准运行中，停止校准后可修改。':'修改数值后应用；本稿范围 20–100%。')}${fieldToggle('below80','允许充电至低于 80% 的电量','默认保护范围为 80–100%。','below80')}${fieldToggle('autoDischarge','自动放电','当前电量高于新限制时自动放电至限制。','autoDischarge',intel)}${row('手动控制',`<button data-action="discharge" ${intel?'disabled':''}>${r.mode==='discharge'?'停止放电':'放电模式'}</button><button data-action="topup">${r.mode==='topup'?'结束充满':'充满'}</button><button data-action="pause">${r.mode==='pause'?'恢复充电':'暂停充电'}</button><button data-action="auto">恢复自动</button>`,'暂停只影响本次充电，不改长期上限及低于80%开关；恢复后继续按原上限。')}${fieldToggle('sailing','航海模式',intel?'Intel 模式不可用。':'充到上限后下降至下限再充电；低于 20% 优先充电。','sailing',intel)}${p.sailing?row('航海电量下限',`${num('sailingLow',20,p.limit-1,'航海电量下限')} %`,'必须小于充电限制；此字段口径为本稿方案。'):''}</div><div class="box">${fieldToggle('heat','过热保护','温度过高暂停充电。','heat')}${p.heat?row('温度阈值',`${num('heatLimit',25,50,'过热保护温度')} °C`,'范围与恢复回差为演示规则，待原生验证。'):''}</div><div class="box">${row('校准模式',`<button data-action="${r.mode==='calibration'?'stopCalibration':'calibration'}" ${intel?'disabled':''}>${r.mode==='calibration'?'停止校准':'开始校准'}</button>`,'上次校准：'+(r.lastCalibration?new Date(r.lastCalibration).toLocaleString():'—'),'calibration')}<div class="stages">${steps.map((x,i)=>`<div class="stage ${r.mode==='calibration'&&r.calStep===i?'active':''}">${i+1}<br>${x}</div>`).join('')}</div>${r.mode==='calibration'?`<p class="note">当前阶段 ${r.calStep+1}/5${r.calStep===3?' · 保持 '+r.hold+'/120 分钟（建议时长）':''}。使用“推进模拟 30 分钟”继续。</p>`:''}<button data-act="advance" style="margin-top:12px">推进模拟 30 分钟</button></div>`}
const widgetNames={level:'电池电量',temperature:'电池温度',capacity:'最大容量',cycles:'循环次数',remaining:'预计续航',power:'耗电量',voltage:'电池电压'};
function metricValues(){const watts=p.graphMode==='instant'?8.6:(p.graphMinutes==5?8.0:p.graphMinutes==60?6.7:7.2);const minutes=Math.round((env.level/100)*57/Math.max(1,watts)*60);return {level:env.level+'%',temperature:env.temp+'°C',capacity:'92%',cycles:'54 次',remaining:Math.floor(minutes/60)+'h '+minutes%60+'m',power:watts.toFixed(1)+' W',voltage:'13.28 V'}}
function dashboardPage(){const vals=metricValues();let apps=[['SuperIsland','0.7 W'],['浏览器','3.2 W'],['视频编辑器','8.6 W']];if(p.includeBackground)apps.push(['后台同步进程','0.9 W']);const min={low:0,medium:1,high:5}[p.energyThreshold];apps=apps.filter(a=>parseFloat(a[1])>=min);return `<div class="metrics">${p.widgets.map(k=>`<div class="metric"><small>${widgetNames[k]}</small><strong>${esc(vals[k])}</strong></div>`).join('')}</div><div class="box"><h2>电池与适配器规格 · 模拟</h2>${row('电池','13.28 V · 0.54 A · 7.16 W','设计容量 6249 mAh / 最大容量 5776 mAh / 当前容量按模拟电量计算。')}${row('电源适配器','20.26 V · 2.2 A','额定 68 W / 系统负载 44.7 W / macOS 状态 Normal。')}${row('续航时间估算',`${select('graphMode',[['average','平均功耗'],['instant','即时功耗']],'估算方式')} ${select('graphMinutes',[[5,'5 分钟'],[15,'15 分钟'],[30,'30 分钟'],[60,'60 分钟']],'平均时间窗口')}`,'估算值为演示数据。')}</div><div class="box"><h2>高功耗应用 · 模拟</h2>${apps.map(a=>row(a[0],a[1])).join('')||'<p class="note">没有高于阈值的应用。</p>'}</div><div class="box"><h2>仪表板小工具</h2><div class="chips">${Object.entries(widgetNames).map(([k,v])=>`<label><input type="checkbox" data-widget="${k}" ${p.widgets.includes(k)?'checked':''}>${v}</label>`).join('')}</div>${p.widgets.map((k,i)=>`<div class="widget-order"><span>${widgetNames[k]}</span><button data-move-widget="${k}" data-dir="-1" ${i===0?'disabled':''}>上移</button><button data-move-widget="${k}" data-dir="1" ${i===p.widgets.length-1?'disabled':''}>下移</button></div>`).join('')}</div>`}
function sleepPage(){return `<div class="box">${row('防止睡眠期间过度充电',select('sleep',[['continue','照原样继续'],['stop','睡眠时停止充电'],['awake','达到充电上限前阻止休眠']],'睡眠行为'),'三个选项互斥。原软件睡眠时轮询减少，可能略高于限制。','sleep')}${p.sleep==='awake'?'<p class="note">达到上限或拔下电源时结束本功能模拟保持。</p>':''}${fieldToggle('stopOnExit','退出应用时停止充电','停止充电的持续性及退出恢复须原生验证。')}${row('不活动时关闭显示屏',select('displayOff',[['system','跟随 macOS'],['5','5 分钟'],['15','15 分钟'],['never','从不']],'显示屏关闭时间'),'校准与合盖期间的屏幕行为需要独立设备验证。')}${fieldToggle('lockOnClose','在睡眠已禁用且合盖时锁定屏幕','与原有保持唤醒功能的策略冲突需统一协调。')}</div><div class="status-card"><strong>当前模拟睡眠策略</strong><p>${r.mode==='calibration'?'校准需要保持系统唤醒。':p.sleep==='awake'&&env.plugged&&env.level<p.limit?'达到上限前保持唤醒。':'遵循当前选择。'} 此信息不是系统休眠断言。</p></div>`}
const powerChoices=[['never','从不'],['always','始终'],['battery','仅使用电池'],['adapter','仅使用电源适配器']];
function energyPage(){return `<div class="box">${row('低电量模式',select('lowPower',powerChoices,'低电量模式'),'改变此项在本稿只保存偏好。','energy')}${row('高功率模式',select('highPower',powerChoices,'高功率模式'),'来自快捷指令定义；仅受支持设备才可实际使用。')}${fieldToggle('backgroundUpdates','后台仪表板更新','设置窗口关闭后继续更新仪表数据。')}${row('高功耗应用阈值',select('energyThreshold',[['low','低使用量'],['medium','中等使用量'],['high','高使用量']],'应用阈值'),'改变后仪表板应用列表随模拟阈值过滤。')}${fieldToggle('includeBackground','包含后台进程','仪表板应用列表同时显示后台进程。')}</div>`}
function taskEditor(id,template){const old=tasks.find(x=>x.id===id),draft=old||{name:'新任务',action:'setLimit',value:80,next:env.now+3600e3,repeat:'daily',enabled:true};if(template){Object.assign(draft,template)}const stamp=new Date(draft.next+8*3600e3).toISOString().slice(0,16);openDialog(old?'编辑定时任务':'添加定时任务',`<div class="fields"><label class="wide">名称<input id="taskName" value="${esc(draft.name)}"></label><label>操作<select id="taskAction">${options([['setLimit','设置充电限制'],['topup','充满'],['pause','暂停充电'],['discharge','放电'],['calibration','校准']],draft.action)}</select></label><label>充电百分比<input type="number" id="taskValue" min="20" max="100" value="${draft.value}"></label><label>首次执行（北京时间）<input type="datetime-local" id="taskDate" value="${stamp}"></label><label>重复<select id="taskRepeat">${options([['once','不重复'],['daily','每天'],['weekly','每周'],['biweekly','每两周'],['monthly','每月（同日，月末取当月末日）']],draft.repeat)}</select></label></div><p>任务字段为候选交互；原软件任务编辑器当前锁定，精确字段与时区规则待核验。</p>`,[{label:'取消'},{label:'保存任务',primary:true,run:()=>{const next=Date.parse($('taskDate').value+'+08:00'),name=$('taskName').value.trim(),value=Number($('taskValue').value);if(!name||!Number.isFinite(next)||value<20||value>100){toast('请输入名称、有效时间和 20–100% 的数值');return false}const item={id:old?.id||String(Date.now()),name,action:$('taskAction').value,value,next,repeat:$('taskRepeat').value,enabled:old?.enabled??true};if(old)tasks[tasks.indexOf(old)]=item;else tasks.push(item);save();render();toast('任务已保存到本地演示')}}])}
function schedulePage(){return `<div class="box"><div class="row"><div><strong>任务</strong><small>仅由模拟时钟触发，不在后台调度系统任务。</small></div><div class="controls"><button data-act="newTask">添加任务</button><button data-act="templates">模板</button></div></div>${tasks.map(t=>`<div class="task"><div class="task-head"><strong>${esc(t.name)}</strong><input type="checkbox" data-task-toggle="${t.id}" aria-label="启用任务 ${esc(t.name)}" ${t.enabled?'checked':''}></div><small>${shortcutNames[t.action]||t.action}${t.action==='setLimit'?' '+t.value+'%':''} · ${new Date(t.next).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})} · ${t.repeat}</small><div class="task-actions"><button data-task-run="${t.id}">现在模拟执行</button><button data-task-edit="${t.id}">编辑</button><button data-task-delete="${t.id}">删除</button></div></div>`).join('')||'<p class="note">暂无任务。添加任务或选择原软件已有的模板主题。</p>'}</div><div class="box">${fieldToggle('catchUp','自动补做错过的任务','使用模拟时间推进验证；校准期间遇到冲突会要求选择。','schedule')}<div class="controls" style="margin-top:12px"><button data-act="advance">推进模拟 30 分钟</button><button data-act="missed">模拟错过 8 小时</button></div></div><div class="box"><h2>任务历史</h2>${history.map(h=>`<div class="history">${esc(h.title)} · ${esc(h.result)}<br><span class="dim">${new Date(h.time).toLocaleString()}</span></div>`).join('')||'<p class="note">尚无模拟执行记录。</p>'}<button data-act="clearHistory" ${history.length?'':'disabled'}>清除任务历史</button></div>`}
function shortcutsPage(){return `<div class="box"><h2>捷径能力</h2><p class="note">安装包 Intents 定义与当前界面共列出以下 12 项。本稿可以测试参数与返回值；未注册 macOS 快捷指令。</p>${row('操作',`<select id="shortcutAction" aria-label="捷径操作">${options(Object.entries(shortcutNames),'getState')}</select>`)}${row('参数','<input id="shortcutValue" aria-label="捷径参数" type="text" value="80">','百分比用数字；电源模式 never / always / battery / adapter；LED always / off / orange / green。')}<button data-act="testShortcut" class="primary" style="margin-top:12px">测试捷径（模拟）</button><pre class="output" id="shortcutOutput">${esc(r.lastOutput||'等待测试')}</pre></div><div class="box">${Object.entries(shortcutNames).map(([k,v])=>row(v,`<button data-shortcut="${k}">选择</button>`)).join('')}</div>`}
const indicators={percentage:'百分比',state:'控制状态',temperature:'温度',capacity:'最大容量',cycles:'循环',voltage:'电压',power:'功率',remaining:'剩余时间',adapter:'适配器功率',system:'系统负载',hardware:'硬件电量',condition:'macOS 条件'};
function displayPage(){return `<div class="box"><h2>电池展开面板</h2>${fieldToggle('showStartup','启动时显示电池面板','仅作本地演示偏好，不改变 SuperIsland 通用启动设置。')}${fieldToggle('showPercent','显示百分比','同步到电池展开页。')}${row('面板内容',`<button data-act="editPopup">编辑内容</button>`,'选择保留的电量、电源、趋势及快捷控制。')}${fieldToggle('reduceTransparency','降低透明度','在原有电池模块表面应用外观偏好。')}</div><div class="box"><h2>现有电池入口显示</h2><p class="note">已按你的决定取消独立菜单栏图标；原软件菜单栏统计配置映射到 SuperIsland 现有电池入口，不新增独立状态项。</p>${row('电池图标样式',select('indicatorStyle',[['native','macOS 原生'],['colored','macOS 彩色'],['ios','iOS 样式']],'图标样式'))}<div class="chips" style="margin-top:12px">${Object.entries(indicators).map(([k,v])=>`<label><input type="checkbox" data-indicator="${k}" ${p.indicators.includes(k)?'checked':''}>${v}</label>`).join('')}</div><p class="note">当前入口预览：${esc($('batteryIcon').title||'仅电池图标')}</p>${p.indicators.map((k,i)=>`<div class="widget-order"><span>${indicators[k]}</span><button data-move-indicator="${k}" data-dir="-1" ${i?'':'disabled'}>上移</button><button data-move-indicator="${k}" data-dir="1" ${i===p.indicators.length-1?'disabled':''}>下移</button></div>`).join('')}${row('显示间距',`${num('indicatorSpacing',0,20,'显示间距')} px`)}${row('更新间隔',`${num('indicatorInterval',2,20,'更新间隔')} 秒`,'原软件建议 5–10 秒；本稿不启动真实采样。')}${row('右击电池入口',select('indicatorRightClick',[['settings','电池设置'],['same','同左击'],['pause','暂停充电']],'右击行为'))}<div class="controls" style="margin-top:12px"><button data-act="resetIndicators">重置显示</button><button data-act="clearIndicators">清除统计项</button></div></div>`}
function otherPage(){return `<div class="box">${fieldToggle('realPercentage','硬件电池百分比','原软件允许按硬件电量控制，可能与 macOS 显示存在偏差。')}${fieldToggle('intelMode','高级 Intel 模式','原软件资源：该模式下放电、航海与校准不可用；重启后限制可能保留，实际值可能有偏差。','hardware')}</div><div class="box"><h2>MagSafe LED</h2>${row('LED 模拟预览',`<span style="color:${p.led==='off'?'#777':p.led==='orange'?'#ffb34d':'#74d596'}">● ${p.led==='off'?'关闭':p.ledBlink&&r.mode==='discharge'?'橙色闪烁':p.ledLimit?(env.level>=p.limit?'绿色 · 已到限':'橙色 · 充电'):'选择：'+p.led}</span>`)}${row('LED 设置',select('led',[['always','始终开启'],['off','始终关闭'],['green','绿色'],['orange','橙色']],'LED 设置'),'原生硬件能力需检查；颜色枚举来自快捷指令与资源，本稿演示。')}${fieldToggle('ledLimit','指示充电限制','根据充电状态切换 LED。')}${fieldToggle('ledBlink','放电期间闪烁橙色','仅兼容 MagSafe 硬件可实际执行。')}</div><div class="box"><h2>辅助程序与恢复</h2><p class="note">${esc(help.hardware)}</p><div class="controls"><button data-act="authorize">模拟授权</button><button data-act="retry">重试控制</button><button data-act="diagnostics">查看诊断</button><button data-act="resetPreferences">恢复默认偏好</button></div></div><p class="note">AlDente 的许可证、付费解锁、遥测、应用更新及卸载入口属于原产品自身管理功能，未复制到 SuperIsland 电池模块。SuperIsland 的开机启动等通用设置仍沿用原设置页。</p>`}
function renderSettings(){document.querySelectorAll('[data-pane]').forEach(b=>b.classList.toggle('active',b.dataset.pane===pane));if(pane!=='battery'){$('settingsContent').innerHTML=`<h1>${panes[pane]}</h1><p class="description">SuperIsland 现有${panes[pane]}设置位置</p><div class="box"><p>此需求稿保留统一设置的导航位置，现有设置项未在本次原型中重做。</p><button data-act="openBattery">查看电池管理</button></div>`;return}const pages={dashboard:dashboardPage,charge:chargePage,sleep:sleepPage,energy:energyPage,schedule:schedulePage,shortcuts:shortcutsPage,display:displayPage,other:otherPage};const scroller=$('settingsContent'),y=scroller.scrollTop;scroller.innerHTML=`<h1>电池管理</h1><p class="description">完整电池控制与保护功能 · 本地交互模拟</p>${row('启用电池管理',`<button data-action="${p.enabled?'off':'on'}">${p.enabled?'关闭':'开启'}</button>`,'启动时自动检查并启用，向用户显示结果；本次手动关闭后停止控制。')}<div class="tabs" role="tablist">${Object.entries(tabs).map(([k,v])=>`<button role="tab" aria-selected="${tab===k}" data-tab="${k}" class="${tab===k?'active':''}">${v}</button>`).join('')}</div>${stateBox()}${pages[tab]()}`;scroller.scrollTop=y}
function renderIslandPages(){for(const [name,id]of Object.entries({overview:'islandOverview',control:'islandControl',trend:'islandTrend'}))$(id).hidden=r.islandTab!==name;document.querySelectorAll('[data-island-tab]').forEach(el=>{const active=el.dataset.islandTab===r.islandTab;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active))});const vals=metricValues();$('islandMetrics').innerHTML=p.widgets.slice(0,6).map(k=>`<div class="island-metric"><small>${esc(widgetNames[k]||k)}</small><strong>${env.scenario==='desktop'?'—':esc(vals[k]||'—')}</strong></div>`).join('');$('overviewStatus').textContent=chargeState()+' · 长期上限 '+p.limit+'%'+(r.mode==='calibration'?' · 阶段 '+(r.calStep+1)+'/5':'');$('controlReadback').textContent='当前电量 '+env.level+'%'+(env.plugged?' · 已接电':' · 未接电')+(r.mode==='pause'?' · 临时停在 '+r.pauseTarget+'%':'');if(env.scenario==='desktop')$('batteryPct').textContent='无内置电池';const last=r.samples[r.samples.length-1];if(last&&last.time===env.now)last.level=env.level;else r.samples.push({time:env.now,level:env.level});r.samples=r.samples.slice(-96);const start=env.now-r.trendHours*3600e3,points=r.samples.filter(x=>x.time>=start);const coords=points.map(x=>({x:Math.max(0,Math.min(600,(x.time-start)/(r.trendHours*3600e3)*600)),y:(100-x.level)/100*48}));const line=coords.map((q,i)=>(i?'L':'M')+q.x.toFixed(1)+' '+q.y.toFixed(1)).join(' ');$('trendLine').setAttribute('d',coords.length>1?line:'');$('trendArea').setAttribute('d',coords.length>1?line+' L'+coords.at(-1).x.toFixed(1)+' 48 L'+coords[0].x.toFixed(1)+' 48 Z':'');$('trendLimit').setAttribute('y1',(100-p.limit)/100*48);$('trendLimit').setAttribute('y2',(100-p.limit)/100*48);$('trendEmpty').hidden=coords.length>1;$('trendCaption').textContent='当前 '+env.level+'% · '+points.length+' 个模拟样本';$('islandTrendWindow').value=r.trendHours;}
function render(){$('startupNotice').hidden=!r.startupVisible;$('startupNotice').classList.toggle('warning',r.startupTitle.includes('未能'));$('startupTitle').textContent=r.startupTitle;$('startupMessage').textContent=r.startupMessage;const state=chargeState();$('batteryPct').textContent=p.showPercent?'▱ '+env.level+'%':'▱';$('batteryFill').style.width=env.level+'%';$('islandLimit').value=p.limit;$('islandLimit').disabled=!!block()||!env.appRunning||r.mode==='calibration';$('islandLimit').title=r.mode==='calibration'?'校准运行中，停止后可调整上限':'拖动设置充电上限；松手后模拟应用';$('islandLimit').setAttribute('aria-valuetext',p.limit+'%，当前允许 '+(p.below80?'20':'80')+' 至 100%');$('islandLimitText').textContent='充电上限 '+p.limit+'%';$('powerSource').textContent=env.plugged?'Power Adapter':'Battery';$('compactStatus').textContent=state;$('batteryIcon').title=p.indicators.map(k=>{const v={percentage:env.level+'%',state,temperature:env.temp+'°C',capacity:'92%',cycles:'54',voltage:'13.28V',power:'7.2W',remaining:'2h15m',adapter:'68W',system:'44.7W',hardware:env.level-1+'%',condition:'Normal'};return v[k]}).join(' · ');$('batteryIcon').style.color=p.indicatorStyle==='colored'?'#76d691':'';$('batteryIcon').style.marginInline=p.indicatorSpacing/4+'px';$('batteryPct').hidden=!p.popupFields.includes('percentage');$('powerSource').hidden=!p.popupFields.includes('source');$('trend').hidden=!p.popupFields.includes('trend');document.querySelector('.quick').hidden=!p.popupFields.includes('controls');document.querySelector('.island').style.background=p.reduceTransparency?'#151515':'#030303';$('quickDischarge').textContent=r.mode==='discharge'?'停止放电':'放电';$('quickTopup').textContent=r.mode==='topup'?'结束充满':'充满';document.querySelectorAll('[data-action="pause"]').forEach(b=>b.textContent=r.mode==='pause'?'恢复充电':'暂停充电');for(const b of document.querySelectorAll('.quick button'))b.disabled=!!block()||!env.plugged||(b.dataset.action==='discharge'&&isIntel());$('envLevel').value=env.level;$('envTemp').value=env.temp;$('envPlugged').checked=env.plugged;$('envScenario').value=env.scenario;$('labStatus').textContent=new Date(env.now).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+' · '+state+(env.lidClosed?' · 已合盖':'')+(env.lidClosed&&p.lockOnClose&&(r.mode==='calibration'||p.sleep==='awake')?' · 已模拟锁屏':'');$('simulateSleep').textContent=env.sleeping?'模拟唤醒':'模拟睡眠';$('simulateLid').textContent=env.lidClosed?'模拟开盖':'模拟合盖';$('simulateExit').textContent=env.appRunning?'模拟退出应用':'模拟启动应用';renderIslandPages();if(!$('settingsWindow').hidden)renderSettings()}
function openSettings(which){pane=which;tab='charge';$('settingsWindow').hidden=false;renderSettings();$('settingsContent').scrollTop=0}
function testShortcut(){const key=$('shortcutAction').value,value=$('shortcutValue').value;let result;if(key==='getLevel')result=env.level;else if(key==='getLimit')result=p.limit;else if(key==='getState')result=chargeState();else if(key==='getTemperature')result=env.temp;else if(key==='setLED'){if(!['always','off','orange','green'].includes(value)){toast('LED 参数无效');return}p.led=value;save();result={saved:value,hardwareApplied:false}}else if(key==='setLow'||key==='setHigh'){if(!powerChoices.some(x=>x[0]===value)){toast('电源模式参数无效');return}p[key==='setLow'?'lowPower':'highPower']=value;save();result={saved:value,hardwareApplied:false}}else{const accepted=operate(key==='setLimit'?'setLimit':key,key==='setLimit'?Number(value):undefined);result={accepted,pendingConfirmation:!$('dialogLayer').hidden,simulation:true}};r.lastOutput=JSON.stringify({operation:key,input:value,result,scope:'local-prototype'},null,2);const out=$('shortcutOutput');if(out)out.textContent=r.lastOutput;if(result?.accepted!==false)toast('已返回本地模拟结果')}
function coverage(){openDialog('功能覆盖与证据',`<p>UI：已逐页读取本机 AlDente 1.39.4；静态：本地化资源、Intents 参数和 REA helper 元数据。专业版锁定部分未执行。</p><table><tr><th>原功能</th><th>本稿覆盖</th><th>证据边界</th></tr>${[['充电上限 / 低于80% / 自动放电','校验、保存、模拟充放电','界面 / 文案 / Intent范围'],['放电 / 充满 / 暂停','独立条件、模式及拔电恢复','界面及资源，非硬件实测'],['航海 / 过热保护','阈值、回差模拟和状态','文案已确认，精确阈值待验证'],['校准','五阶段、停止、原上限恢复','阶段来自界面，保持时长为方案'],['仪表板 / 能源','指标、小工具排序和应用筛选','指标数据为模拟'],['睡眠行为','互斥选项、退出、屏幕、合盖锁屏','未修改系统断言'],['定时任务','新增编辑、模板、重复、补做、冲突、历史','编辑器锁定，字段为候选方案'],['捷径 12 项','参数校验及本地返回','未注册苹果快捷指令'],['显示 / MagSafe / Intel','偏好、禁用边界及显示预览','无独立状态图标，硬件待验证']].map(a=>`<tr>${a.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</table><p>原生功能尚未实现。不能把此原型的模拟执行称为电池硬件执行。</p>`,[{label:'关闭'}])}
const actions={openBattery:()=>openSettings('battery'),applyLimit:()=>operate('setLimit',r.draftLimit),advance,authorize:()=>{confirm('模拟辅助程序授权？','仅切换演示场景；不会安装辅助程序或触发系统授权。',()=>{env.scenario='ok';r.error='';render();toast('演示环境设为已授权')})},retry:()=>{r.error='';const a=r.retry;r.retry=null;if(a)operate(a.action,a.value);else render()},newTask:()=>taskEditor(),templates:()=>openDialog('选择任务模板','<p>模板主题来自原软件资源；执行时间和重复字段为本稿方案。</p><div class="controls"><button data-template="monday">周一早晨充满</button><button data-template="weekend">周末充满</button><button data-template="monthly">每月校准</button><button data-template="biweekly">每两周校准</button></div>',[{label:'关闭'}]),missed:()=>{env.now+=8*3600e3;advance()},clearHistory:()=>confirm('清除模拟任务历史？','仅清除本地演示记录。',()=>{history=[];save();render()}),testShortcut,resetIndicators:()=>{p.indicators=['percentage','state'];p.indicatorStyle='native';save();render()},clearIndicators:()=>{p.indicators=[];save();render()},editPopup:()=>openDialog('电池面板内容',`<p>布局继续使用原有电池模块；从中选择显示内容。</p><div class="chips">${[['percentage','电量'],['source','电源'],['trend','趋势'],['controls','快捷控制']].map(([k,v])=>`<label><input type="checkbox" data-popup="${k}" ${p.popupFields.includes(k)?'checked':''}>${v}</label>`).join('')}</div>`,[{label:'完成'}]),diagnostics:()=>openDialog('模拟诊断','<pre class="output">'+esc(JSON.stringify({scenario:env.scenario,preferences:p,controllerMode:r.mode,hardwareConnected:false},null,2))+'</pre>',[{label:'关闭'}]),resetPreferences:()=>confirm('恢复电池管理默认偏好？','仅重置本地需求稿，不修改 SuperIsland 或 AlDente 设置。',()=>{p=defaults();stopCalibration();save();render()})};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.dialog!==undefined){const a=dialogCallback?.[Number(b.dataset.dialog)];if(!a)return;const fn=a.run;const ret=fn?.();if(ret!==false)closeDialog();return}if(b.dataset.help){openDialog('功能说明',`<p>${esc(help[b.dataset.help])}</p>`,[{label:'关闭'}]);return}if(b.dataset.islandTab){r.islandTab=b.dataset.islandTab;render();return}if(b.dataset.pane){pane=b.dataset.pane;renderSettings();return}if(b.dataset.tab){tab=b.dataset.tab;renderSettings();return}if(b.dataset.action){operate(b.dataset.action);return}if(b.dataset.act){actions[b.dataset.act]?.();return}if(b.dataset.shortcut){$('shortcutAction').value=b.dataset.shortcut;toast('已选择 '+shortcutNames[b.dataset.shortcut]);return}if(b.dataset.taskEdit){taskEditor(b.dataset.taskEdit);return}if(b.dataset.taskRun){executeTask(tasks.find(x=>x.id===b.dataset.taskRun));return}if(b.dataset.taskDelete){confirm('删除任务？','只删除此本地模拟任务。',()=>{tasks=tasks.filter(x=>x.id!==b.dataset.taskDelete);save();render()});return}if(b.dataset.template){const name={monday:'周一早晨充满',weekend:'周末充满',monthly:'每月校准',biweekly:'每两周校准'}[b.dataset.template];closeDialog();taskEditor(null,{name,action:['monthly','biweekly'].includes(b.dataset.template)?'calibration':'topup',value:100,next:b.dataset.template==='monday'?nextWeekday(1,5):b.dataset.template==='weekend'?nextWeekday(6,7):b.dataset.template==='monthly'?calendarMonth(env.now):env.now+14*86400e3,repeat:b.dataset.template==='monthly'?'monthly':b.dataset.template==='biweekly'?'biweekly':'weekly'});return}const kind=b.dataset.moveWidget?'widgets':b.dataset.moveIndicator?'indicators':null;if(kind){const value=b.dataset.moveWidget||b.dataset.moveIndicator,i=p[kind].indexOf(value),j=i+Number(b.dataset.dir);[p[kind][i],p[kind][j]]=[p[kind][j],p[kind][i]];save();render()}});
document.addEventListener('change',e=>{const el=e.target;if(el.hasAttribute('data-limit-draft')){r.draftLimit=Number(el.value);return}if(el.dataset.pref){const k=el.dataset.pref;if(el.type==='checkbox')toggle(k);else preference(k,el.type==='number'?Number(el.value):el.value);return}for(const [attr,key]of[['widget','widgets'],['indicator','indicators'],['popup','popupFields']]){if(el.dataset[attr]){const v=el.dataset[attr];p[key]=el.checked?[...p[key],v]:p[key].filter(x=>x!==v);save();render();return}}if(el.dataset.taskToggle){tasks.find(x=>x.id===el.dataset.taskToggle).enabled=el.checked;save()}});
function commitIslandLimit(){if(r.limitGestureHandled)return;r.limitGestureHandled=true;const value=Math.max(p.below80?20:80,Math.min(100,Number($('islandLimit').value))),belowAttempt=r.dragClamped&&!p.below80;if(belowAttempt){render();openDialog('低充电限值','<p>在最新版本的 macOS 中，苹果建议将充电上限设置在 80% 至 100% 之间。如果想设置更低的上限，可以在电池管理设置中启用“允许充电至低于 80% 的电量”。</p>',[{label:'取消'},{label:'打开设置',primary:true,run:()=>{openSettings('battery');const option=document.querySelector('[data-pref="below80"]');option.closest('.row').classList.add('setting-highlight');option.scrollIntoView({block:'center'});option.focus();}}]);return}if(operate('setLimit',value))toast('已模拟应用充电上限 '+value+'%');render()}
$('islandLimit').onpointerdown=()=>{r.dragClamped=false;r.limitGestureHandled=false};$('islandLimit').onkeydown=()=>{r.dragClamped=false;r.limitGestureHandled=false};$('islandLimit').oninput=e=>{const raw=Number(e.target.value),lower=p.below80?20:80;const value=Math.max(lower,Math.min(100,raw));r.dragClamped=r.dragClamped||raw<lower;e.target.value=value;r.dragLimit=value;$('islandLimitText').textContent='充电上限 '+value+'% · 松手应用';e.target.setAttribute('aria-valuetext',value+'%，松手应用')};$('islandLimit').onchange=commitIslandLimit;$('islandLimit').onpointerup=commitIslandLimit;$('islandLimit').onpointercancel=()=>{r.limitGestureHandled=true;render()};$('islandTrendWindow').onchange=e=>{r.trendHours=Number(e.target.value);render()};$('globalSettings').onclick=()=>openSettings('general');$('batterySettings').onclick=()=>openSettings('battery');$('batteryIcon').onclick=()=>{r.islandTab='overview';render()};$('batteryIcon').oncontextmenu=e=>{e.preventDefault();if(p.indicatorRightClick==='settings')openSettings('battery');else if(p.indicatorRightClick==='pause')operate('pause');else toast('当前已显示电池模块')};$('closeSettings').onclick=()=>$('settingsWindow').hidden=true;$('coverageOpen').onclick=coverage;$('startupSettings').onclick=()=>openSettings('battery');$('dismissStartup').onclick=()=>{r.startupVisible=false;render()};$('advance').onclick=advance;$('simulateSleep').onclick=()=>{if(!env.sleeping&&(r.mode==='calibration'||(p.sleep==='awake'&&env.plugged&&env.level<p.limit))){toast('当前模拟策略阻止休眠');return}env.sleeping=!env.sleeping;render()};$('simulateLid').onclick=()=>{env.lidClosed=!env.lidClosed;render();toast(env.lidClosed&&p.lockOnClose?'已模拟合盖和锁屏判定':'机盖模拟状态已更新')};$('simulateExit').onclick=()=>{env.appRunning=!env.appRunning;if(!env.appRunning){if(r.mode==='calibration')stopCalibration();r.pauseTarget=null;r.startupVisible=false;render()}else autoEnableAtStartup()};$('reset').onclick=()=>{confirm('重置完整演示？','重置本地偏好、模拟时间、任务和记录。',()=>{p=defaults();tasks=[];history=[];Object.assign(env,{sleeping:false,lidClosed:false,appRunning:true,level:76,temp:30,plugged:true,scenario:'ok',now:new Date('2026-10-29T10:00:00+08:00').getTime()});Object.assign(r,{pauseTarget:null,startupVisible:false,islandTab:'overview',trendHours:6,samples:[{time:env.now,level:env.level}],draftLimit:80,mode:'auto',calStep:0,hold:0,calSaved:null,lastCalibration:null,error:'',retry:null,sailingHold:false});save();render();$('toast').hidden=true})};$('envLevel').onchange=e=>{env.level=Math.max(0,Math.min(100,Number(e.target.value)||0));render()};$('envTemp').onchange=e=>{env.temp=Number(e.target.value)||0;render()};$('envPlugged').onchange=e=>{env.plugged=e.target.checked;if(!env.plugged){if(r.mode==='calibration')stopCalibration();r.mode='auto';r.pauseTarget=null;r.sailingHold=false}render()};$('envScenario').onchange=e=>{env.scenario=e.target.value;render()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('dialogLayer').hidden)closeDialog();else $('settingsWindow').hidden=true}});autoEnableAtStartup();const requestedView=new URLSearchParams(location.search).get('view');if(requestedView&&Object.hasOwn(tabs,requestedView)){openSettings('battery');tab=requestedView;renderSettings();$('settingsContent').scrollTop=0}else if(p.showStartup)toast('已模拟启动时显示原有电池面板');
})();
